                return ((props_bitfield[bitfield_row][0] & 0x7f) >> 0); /* mask: 00000000000000000000000001111111 */

        case MVM_UNICODE_PROPERTY_CASE_FOLDING: /* Case_Folding bits:11 offset:0 */
                return ((props_bitfield[bitfield_row][1] & 0xffe00000) >> 21); /* mask: 11111111111000000000000000000000 */

