                result_val = ((props_bitfield[bitfield_row][1] & 0x1ff000) >> 12); /* mask: 00000000000111111111000000000000 */
                return result_val < 429 ? (result_val == -1
                    ? Bidi_Mirroring_Glyph_enums[0] : Bidi_Mirroring_Glyph_enums[result_val]) : 0;

        case MVM_UNICODE_PROPERTY_BLOCK: /* Block bits:9 offset:20 */
                return ((props_bitfield[bitfield_row][1] & 0xff8) >> 3); /* mask: 00000000000000000000111111111000 */

