        case MVM_UNICODE_PROPERTY_SPECIAL_CASING: /* Special_Casing bits:7 offset:23 */
                return ((props_bitfield[bitfield_row][2] & 0x1fc) >> 2); /* mask: 00000000000000000000000111111100 */

