                return ((props_bitfield[bitfield_row][2] & 0x3) >> 0); /* mask: 00000000000000000000000000000011 */

        case MVM_UNICODE_PROPERTY_CANONICAL_COMBINING_CLASS: /* Canonical_Combining_Class bits:6 offset:0 */
                return ((props_bitfield[bitfield_row][3] & 0xfc000000) >> 26); /* mask: 11111100000000000000000000000000 */

        case MVM_UNICODE_PROPERTY_LINE_BREAK: /* Line_Break bits:6 offset:6 */
                return ((props_bitfield[bitfield_row][3] & 0x3f00000) >> 20); /* mask: 00000011111100000000000000000000 */

